head.script:
scwin.gVar = {
    "cInitClass" : null,
    "cInitStyle" : ""
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[body > M > focus]<br/>컴포넌트로 포커스를 이동시킵니다.",
    "validation" : [
        "포커스를 받을 수 있는 컴포넌트(InputBox, Button, TextArea 등)에 포커스가 이동되어야 합니다.",
        "포커스를 받을 수 없는 컴포넌트는 관련 속성(tabIndex 등)을 설정 시 포커스가 이동되어야 합니다.",
    ]
} 



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  body 는 동적 생성/삭제가 불가하므로 최초 렌더된 body 컴포넌트를 그대로 대상으로 사용하고,
//  "Target 재생성" 은 최초 렌더 시점의 class / style 상태로 되돌리는 것으로 대응한다.
scwin.comp_init = function () {
    let objBody = scwin.getBody();

    if (scwin.gVar["cInitClass"] === null) {
        // 최초 1회 : 초기 class / style 보관
        scwin.gVar["cInitClass"] = objBody.render.className;
        scwin.gVar["cInitStyle"] = objBody.render.getAttribute("style") || "";
    } else {
        // 재생성 : 초기 상태로 복원 + 기존 이벤트 해제
        objBody.render.className = scwin.gVar["cInitClass"];
        objBody.render.setAttribute("style", scwin.gVar["cInitStyle"]);
        objBody.unbind("onfocus", scwin.target1_onfocus);
    }

    // body 는 기본적으로 포커스를 받을 수 없는 컴포넌트(tabIndex=-1)이므로
    //  focus() 로 포커스가 이동하려면 tabIndex 가 설정되어 있어야 한다(유효성②).
    //  body 는 재생성 대상이 아니라 속성 주입 경로가 없으므로 render 에 직접 설정한다.
    objBody.render.setAttribute("tabIndex", "0");

    // body 는 onclick/onfocus 등을 선언 이벤트로 제공하지 않으므로 bind() 로 등록한다
    objBody.bind("onfocus", scwin.target1_onfocus);
}



// (검증) focus() 호출
//  body 는 아무것도 포커스되지 않은 상태의 기본 activeElement 이므로, 그대로 호출하면
//  포커스 이동 없이도 성공처럼 보인다. 따라서 먼저 다른 요소(실행 버튼)로 포커스를 옮긴 뒤
//  focus() 를 호출하여 이동 여부를 판정한다.
scwin.btn_focus_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    let objBody = scwin.getBody();

    bottom.setReturnValue("호출 전 activeElement : " + document.activeElement.tagName
        + " | body tabIndex 속성 : " + (objBody.render.getAttribute("tabIndex") === null ? "(없음)" : objBody.render.getAttribute("tabIndex")));

    objBody.focus();

    bottom.setReturnValue("호출 후 activeElement : " + document.activeElement.tagName);
};



// 테스트 샘플의 이벤트 처리
scwin.target1_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onfocus 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("e:" + e);   
}

// body 컴포넌트 조회
//  body 는 화면과 함께 렌더되는 컴포넌트로 $p.dynamicCreate / remove 대상이 아니고
//  공통 생성 함수($c.gcm.createBasicXxx)도 없어 공통 base(common_M) wrap 패턴을 쓸 수 없다.
//  <body id="target1"> 로 선언해도 body 는 root 요소라 scope 전역(target1)으로 등록되지 않으며
//  $p.getComponentById("target1") 도 scope 접두어가 적용되지 않아 undefined 를 반환하므로,
//  정적 선언된 자식(grp_main)의 parentControl 로 조회한다.
scwin.getBody = function () {
    return grp_main.parentControl;
}
